type PaymentsHandler struct {
	Models                      *data.Models
	DBConnectionPool            db.DBConnectionPool
	AuthManager                 auth.AuthManager
	CrashTrackerClient          crashtracker.CrashTrackerClient
	DistributionAccountResolver signing.DistributionAccountResolver
	DirectPaymentService        *services.DirectPaymentService
}

type RetryPaymentsRequest struct {
	PaymentIDs []string `json:"payment_ids"`
}

func (r *RetryPaymentsRequest) validate() *httperror.HTTPError {
	validator := validators.NewValidator()
	validator.Check(len(r.PaymentIDs) != 0, "payment_ids", "payment_ids should not be empty")
	if validator.HasErrors() {
		return httperror.BadRequest("", nil, validator.Errors)
	}

	return nil
}

// decorateWithCircleTransactionInfo is not gated on the account being Circle: resolution is per
// payment row, and non-Circle tenants simply have no circle_transfer_requests rows to find.
func (p PaymentsHandler) decorateWithCircleTransactionInfo(ctx context.Context, sqlExec db.SQLExecuter, payments []data.Payment) ([]data.Payment, error) {
	if err := p.Models.CircleTransferRequests.PopulateCircleTransactionInfo(ctx, sqlExec, payments); err != nil {
		return nil, fmt.Errorf("populating circle transaction info: %w", err)
	}

	return payments, nil
}

func (p PaymentsHandler) GetPayment(w http.ResponseWriter, r *http.Request) {
	paymentID := chi.URLParam(r, "id")
	ctx := r.Context()

	payment, err := p.Models.Payment.Get(ctx, paymentID, p.DBConnectionPool)
	if err == nil {
		// Membership-filtered visibility: 404 outside the caller's scope — existence
		// is never disclosed. payment.SourceWalletID is the payment's own persisted source
		// wallet (guaranteed non-empty for both disbursement and direct payments).
		scope, scopeErr := resolveWalletReadScope(ctx, p.AuthManager, p.Models)
		if scopeErr != nil {
			scopeErr.Render(w)
			return
		}
		if scope != nil && !walletInReadScope(scope, payment.SourceWalletID) {
			httperror.NotFound("payment not found", nil, nil).Render(w)
			return
		}
	}
	if err != nil {
		if errors.Is(err, data.ErrRecordNotFound) {
			errorResponse := fmt.Sprintf("Cannot retrieve payment with ID: %s", paymentID)
			httperror.NotFound(errorResponse, err, nil).Render(w)
			return
		} else {
			msg := fmt.Sprintf("Cannot retrieve payment with id %s", paymentID)
			httperror.InternalError(ctx, msg, err, nil).Render(w)
			return
		}
	}

	payments, err := p.decorateWithCircleTransactionInfo(ctx, p.DBConnectionPool, []data.Payment{*payment})
	if err != nil {
		httperror.InternalError(ctx, "Cannot retrieve payment with circle info", err, nil).Render(w)
		return
	}

	httpjson.RenderStatus(w, http.StatusOK, payments[0], httpjson.JSON)
}

func (p PaymentsHandler) GetPayments(w http.ResponseWriter, r *http.Request) {
	validator := validators.NewPaymentQueryValidator()
	queryParams := validator.ParseParametersFromRequest(r)
	var err error

	if validator.HasErrors() {
		httperror.BadRequest("request invalid", nil, validator.Errors).Render(w)
		return
	}

	queryParams.Filters = validator.ValidateAndGetPaymentFilters(queryParams.Filters)
	if validator.HasErrors() {
		httperror.BadRequest("request invalid", nil, validator.Errors).Render(w)
		return
	}

	ctx := r.Context()

	// Per-account list scope: narrow to the selected account (X-Wallet-Id) when set, else full
	// visibility (owner tenant-wide, member = their wallets).
	scope, scopeErr := resolveWalletListScope(ctx, r, p.AuthManager, p.Models)
	if scopeErr != nil {
		scopeErr.Render(w)
		return
	}
	if scope != nil {
		queryParams.Filters[data.FilterKeySourceWalletIDs] = scope
	}

	response, err := p.getPaymentsWithCount(ctx, queryParams)
	if err != nil {
		httperror.InternalError(ctx, "Cannot retrieve payments", err, nil).Render(w)
		return
	}
	if response.Total == 0 {
		httpjson.RenderStatus(w, http.StatusOK, httpresponse.NewEmptyPaginatedResponse(), httpjson.JSON)
	} else {
		response, errGet := httpresponse.NewPaginatedResponse(r, response.Result, queryParams.Page, queryParams.PageLimit, response.Total)
		if errGet != nil {
			httperror.InternalError(ctx, "Cannot create paginated payments response", errGet, nil).Render(w)
			return
		}
		httpjson.RenderStatus(w, http.StatusOK, response, httpjson.JSON)
	}
}

func (p PaymentsHandler) RetryPayments(rw http.ResponseWriter, req *http.Request) {
	ctx := req.Context()

	token, err := sdpcontext.GetTokenFromContext(ctx)
	if err != nil {
		httperror.Unauthorized("", nil, nil).Render(rw)
		return
	}

	user, err := p.AuthManager.GetUser(ctx, token)
	if err != nil {
		httperror.InternalError(ctx, "", err, nil).Render(rw)
		return
	}

	var reqBody RetryPaymentsRequest
	if err = httpdecode.DecodeJSON(req, &reqBody); err != nil {
		httperror.BadRequest("", err, nil).Render(rw)
		return
	}

	if err := reqBody.validate(); err != nil {
		err.Render(rw)
		return
	}

	// retrying is a state transition — gate each payment on its source wallet.
	for _, retryPaymentID := range reqBody.PaymentIDs {
		retryPayment, getErr := p.Models.Payment.Get(ctx, retryPaymentID, p.DBConnectionPool)
		if getErr != nil {
			if errors.Is(getErr, data.ErrRecordNotFound) {
				httperror.NotFound("payment not found", getErr, nil).Render(rw)
			} else {
				httperror.InternalError(ctx, "Cannot load payment", getErr, nil).Render(rw)
			}
			return
		}
		if httpErr := ensureWalletActionAllowed(ctx, p.AuthManager, p.Models, retryPayment.SourceWalletID,
			data.FinancialControllerUserRole, data.BusinessUserRole); httpErr != nil {
			httpErr.Render(rw)
			return
		}
	}

	err = db.RunInTransaction(ctx, p.DBConnectionPool, nil, func(dbTx db.DBTransaction) error {
		err = p.Models.Payment.RetryFailedPayments(ctx, dbTx, user.Email, reqBody.PaymentIDs...)
		if err != nil {
			return fmt.Errorf("retrying failed payments: %w", err)
		}

		var tnt *schema.Tenant
		if tnt, err = sdpcontext.GetTenantFromContext(ctx); err != nil {
			return fmt.Errorf("getting tenant from context: %w", err)
		} else if tnt.DistributionAccountType.IsCircle() {
			_, err = p.Models.CircleRecipient.ResetRecipientsForRetryIfNeeded(ctx, dbTx, reqBody.PaymentIDs...)
			if err != nil {
				return fmt.Errorf("resetting circle recipients for retry if needed: %w", err)
			}
		}
		return nil
	})
	if err != nil {
		if errors.Is(err, data.ErrMismatchNumRowsAffected) {
			httperror.BadRequest("Invalid payment ID(s) provided. All payment IDs must exist and be in the 'FAILED' state.", err, nil).Render(rw)
			return
		}

		httperror.InternalError(ctx, "", err, nil).Render(rw)
		return
	}

	httpjson.RenderStatus(rw, http.StatusOK, map[string]string{"message": "Payments retried successfully"}, httpjson.JSON)
}

func (p PaymentsHandler) getPaymentsWithCount(ctx context.Context, queryParams *data.QueryParams) (*utils.ResultWithTotal, error) {
	return db.RunInTransactionWithResult(ctx, p.DBConnectionPool, nil, func(dbTx db.DBTransaction) (response *utils.ResultWithTotal, innerErr error) {
		totalPayments, innerErr := p.Models.Payment.Count(ctx, queryParams, dbTx)
		if innerErr != nil {
			return nil, fmt.Errorf("error counting payments: %w", innerErr)
		}

		var payments []data.Payment
		if totalPayments != 0 {
			payments, innerErr = p.Models.Payment.GetAll(ctx, queryParams, dbTx, data.QueryTypeSelectPaginated)
			if innerErr != nil {
				return nil, fmt.Errorf("error querying payments: %w", innerErr)
			}
		}

		payments, err := p.decorateWithCircleTransactionInfo(ctx, dbTx, payments)
		if err != nil {
			return nil, fmt.Errorf("adding circle info to payments: %w", err)
		}

		return utils.NewResultWithTotal(totalPayments, payments), nil
	})
}

type PatchPaymentStatusRequest struct {
	Status string `json:"status"`
}

type UpdatePaymentStatusResponseBody struct {
	Message string `json:"message"`
}

func (p PaymentsHandler) PatchPaymentStatus(w http.ResponseWriter, r *http.Request) {
	var patchRequest PatchPaymentStatusRequest
	err := json.NewDecoder(r.Body).Decode(&patchRequest)
	if err != nil {
		httperror.BadRequest("invalid request body", err, nil).Render(w)
		return
	}

	// validate request
	toStatus, err := data.ToPaymentStatus(patchRequest.Status)
	if err != nil {
		httperror.BadRequest("invalid status", err, nil).Render(w)
		return
	}

	paymentManagementService := services.NewPaymentManagementService(p.Models, p.DBConnectionPool)
	response := UpdatePaymentStatusResponseBody{}

	ctx := r.Context()
	paymentID := chi.URLParam(r, "id")

	// every state transition is gated on the payment's source wallet.
	payment, err := p.Models.Payment.Get(ctx, paymentID, p.DBConnectionPool)
	if err != nil {
		if errors.Is(err, data.ErrRecordNotFound) {
			httperror.NotFound(services.ErrPaymentNotFound.Error(), err, nil).Render(w)
		} else {
			httperror.InternalError(ctx, "Cannot load payment", err, nil).Render(w)
		}
		return
	}
	if httpErr := ensureWalletActionAllowed(ctx, p.AuthManager, p.Models, payment.SourceWalletID,
		data.FinancialControllerUserRole); httpErr != nil {
		httpErr.Render(w)
		return
	}

	switch toStatus {
	case data.CanceledPaymentStatus:
		err = paymentManagementService.CancelPayment(ctx, paymentID)
		response.Message = "Payment canceled"
	default:
		err = services.ErrPaymentStatusCantBeChanged
	}

	if err != nil {
		switch {
		case errors.Is(err, services.ErrPaymentNotFound):
			httperror.NotFound(services.ErrPaymentNotFound.Error(), err, nil).Render(w)
		case errors.Is(err, services.ErrPaymentNotReadyToCancel):
			httperror.BadRequest(services.ErrPaymentNotReadyToCancel.Error(), err, nil).Render(w)
		case errors.Is(err, services.ErrPaymentStatusCantBeChanged):
			httperror.BadRequest(services.ErrPaymentStatusCantBeChanged.Error(), err, nil).Render(w)
		default:
			msg := fmt.Sprintf("Cannot update payment ID %s with status: %s", paymentID, toStatus)
			httperror.InternalError(ctx, msg, err, nil).Render(w)
		}
		return
	}

	httpjson.RenderStatus(w, http.StatusOK, response, httpjson.JSON)
}

func (p PaymentsHandler) PostDirectPayment(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()

	var req validators.CreateDirectPaymentRequest
	if err := httpdecode.DecodeJSON(r, &req); err != nil {
		httperror.BadRequest("invalid request body", err, nil).Render(w)
		return
	}

	validator := validators.NewDirectPaymentValidator()
	validatedReq := validator.ValidateCreateDirectPaymentRequest(&req)
	if validator.HasErrors() {
		httperror.BadRequest("request invalid", nil, validator.Errors).Render(w)
		return
	}

	userID, err := sdpcontext.GetUserIDFromContext(ctx)
	if err != nil {
		httperror.Unauthorized("", nil, nil).Render(w)
		return
	}
	user, err := p.AuthManager.GetUserByID(ctx, userID)
	if err != nil {
		if errors.Is(err, auth.ErrUserNotFound) {
			httperror.Unauthorized("", err, nil).Render(w)
			return
		}
		httperror.InternalError(ctx, "Cannot get user", err, nil).Render(w)
		return
	}

	serviceReq := services.CreateDirectPaymentRequest{
		Amount:            validatedReq.Amount,
		Asset:             convertAssetReference(validatedReq.Asset),
		Receiver:          convertReceiverReference(validatedReq.Receiver),
		Wallet:            convertWalletReference(validatedReq.Wallet),
		ExternalPaymentID: validatedReq.ExternalPaymentID,
	}

	// Routing: explicit source wallet via X-Wallet-Id (single-wallet tenants may omit).
	sourceWallet, walletErr := resolveSourceWalletForWrite(ctx, r, p.AuthManager, p.Models,
		data.FinancialControllerUserRole, data.BusinessUserRole)
	if walletErr != nil {
		walletErr.Render(w)
		return
	}
	serviceReq.SourceWalletID = sourceWallet.ID

	distAccount, accountErr := resolveSourceDistributionAccount(ctx, p.DistributionAccountResolver, sourceWallet,
		"the source wallet has no funded distribution account yet")
	if accountErr != nil {
		accountErr.Render(w)
		return
	}

	payment, err := p.DirectPaymentService.CreateDirectPayment(ctx, serviceReq, user, &distAccount)
	if err != nil {
		var (
			validationErr         services.ValidationError
			notFoundErr           services.NotFoundError
			unsupportedErr        services.UnsupportedError
			ambiguousErr          services.AmbiguousReferenceError
			insufficientFundsErr  services.InsufficientBalanceForDirectPaymentError
			walletDisabledErr     services.WalletNotEnabledError
			assetNotSupportedErr  services.AssetNotSupportedByWalletError
			recvErr               services.ReceiverWalletNotFoundError
			recvWalletNotReadyErr services.ReceiverWalletNotReadyForPaymentError
			trustErr              services.TrustlineNotFoundError
			accErr                services.AccountNotFoundError
			circleAccErr          services.CircleAccountNotActivatedError
			circleAssetErr        services.CircleAssetNotSupportedError
		)

		switch {
		case errors.As(err, &validationErr):
			httperror.BadRequest(validationErr.Error(), err, nil).Render(w)
		case errors.As(err, &notFoundErr):
			httperror.NotFound(notFoundErr.Error(), err, nil).Render(w)
		case errors.As(err, &unsupportedErr):
			httperror.BadRequest(unsupportedErr.Error(), err, nil).Render(w)
		case errors.As(err, &ambiguousErr):
			httperror.BadRequest(ambiguousErr.Error(), err, nil).Render(w)
		case errors.As(err, &insufficientFundsErr):
			log.Ctx(ctx).Error(insufficientFundsErr)
			httperror.BadRequest(insufficientFundsErr.Error(), err, nil).Render(w)
		case errors.As(err, &walletDisabledErr):
			httperror.BadRequest(walletDisabledErr.Error(), err, nil).Render(w)
		case errors.As(err, &assetNotSupportedErr):
			httperror.BadRequest(assetNotSupportedErr.Error(), err, nil).Render(w)
		case errors.As(err, &recvWalletNotReadyErr):
			httperror.BadRequest(recvWalletNotReadyErr.Error(), err, nil).Render(w)
		case errors.As(err, &recvErr):
			httperror.BadRequest(recvErr.Error(), err, nil).Render(w)
		case errors.As(err, &trustErr):
			errorMsg := fmt.Sprintf("%s. Please add a trustline for this asset to your distribution account, or choose a different asset that already has a trustline.", trustErr.Error())
			httperror.BadRequest(errorMsg, err, nil).Render(w)
		case errors.As(err, &circleAccErr):
			errorMsg := fmt.Sprintf("%s. Please complete the Circle account activation process...", circleAccErr.Error())
			httperror.BadRequest(errorMsg, err, nil).Render(w)
		case errors.As(err, &circleAssetErr):
			errorMsg := fmt.Sprintf("%s. Please choose a different asset supported by Circle...", circleAssetErr.Error())
			httperror.BadRequest(errorMsg, err, nil).Render(w)
		case errors.As(err, &accErr):
			errorMsg := fmt.Sprintf("%s. Please ensure your distribution account exists and is funded on the Stellar network.", accErr.Error())
			httperror.BadRequest(errorMsg, err, nil).Render(w)
		default:
			httperror.InternalError(ctx, "creating payment", err, nil).Render(w)
		}

		return
	}

	httpjson.RenderStatus(w, http.StatusCreated, payment, httpjson.JSON)
}

func convertAssetReference(asset validators.DirectPaymentAsset) services.AssetReference {
	return services.AssetReference{
		ID:         asset.ID,
		Type:       asset.Type,
		Code:       asset.Code,
		Issuer:     asset.Issuer,
		ContractID: asset.ContractID,
	}
}

func convertReceiverReference(receiver validators.DirectPaymentReceiver) services.ReceiverReference {
	return services.ReceiverReference{
		ID:            receiver.ID,
		Email:         receiver.Email,
		PhoneNumber:   receiver.PhoneNumber,
		WalletAddress: receiver.WalletAddress,
	}
}

func convertWalletReference(wallet validators.DirectPaymentWallet) services.WalletReference {
	return services.WalletReference{
		ID:      wallet.ID,
		Address: wallet.Address,
	}
}

package httpresponse

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// PaginatedResponse is a response that contains pagination information.
type PaginatedResponse struct {
	Pagination PaginationInfo  `json:"pagination"`
	Data       json.RawMessage `json:"data"`
}

type PaginationInfo struct {
	Next  string `json:"next,omitempty"`
	Prev  string `json:"prev,omitempty"`
	Pages int    `json:"pages"`
	Total int    `json:"total"`
}

// NewEmptyPaginatedResponse returns a PaginatedResponse with an empty data and 0 pages.
//
//	This is useful for returning an empty list.
func NewEmptyPaginatedResponse() PaginatedResponse {
	return PaginatedResponse{
		Pagination: PaginationInfo{
			Pages: 0,
			Total: 0,
		},
		Data: json.RawMessage("[]"),
	}
}

// NewPaginatedResponse returns a PaginatedResponse with pagination information.
func NewPaginatedResponse(r *http.Request, data interface{}, currentPage, pageLimit, totalItems int) (PaginatedResponse, error) {
	if pageLimit <= 0 {
		return PaginatedResponse{}, fmt.Errorf("page_limit must be a positive integer")
	}
	totalPages := (totalItems + pageLimit - 1) / pageLimit
	pagination := PaginationInfo{Pages: totalPages, Total: totalItems}

	baseURL := *r.URL
	q := baseURL.Query()
	q.Del("page")

	if currentPage < totalPages {
		q.Set("page", fmt.Sprintf("%d", currentPage+1))
		baseURL.RawQuery = q.Encode()
		pagination.Next = baseURL.String()
	}

	if currentPage > 1 {
		q.Set("page", fmt.Sprintf("%d", currentPage-1))
		baseURL.RawQuery = q.Encode()
		pagination.Prev = baseURL.String()
	}

	dataBytes, err := json.Marshal(data)
	if err != nil {
		return PaginatedResponse{}, fmt.Errorf("marshalling data: %w", err)
	}

	return PaginatedResponse{
		Pagination: pagination,
		Data:       dataBytes,
	}, nil
}

package middleware

import (
	"context"
	"fmt"
	"net"
	"net/http"
	"strings"
	"time"

	"github.com/dgraph-io/ristretto"
	"github.com/stellar/go-stellar-sdk/support/log"

	"github.com/stellar/stellar-disbursement-platform-backend/internal/data"
	"github.com/stellar/stellar-disbursement-platform-backend/internal/sdpcontext"
	"github.com/stellar/stellar-disbursement-platform-backend/internal/serve/httperror"
)

// apiKeyCacheTTL bounds how long a validated API key can be served from cache
// without a fresh DB check. It exists only as defense-in-depth (e.g. across
// multiple server instances, each with their own in-process cache); within a
// single instance, Invalidate is called synchronously by the API key
// handler on every permission/IP-allowlist change and on delete, so a given
// instance never needs to wait out the TTL to observe an update. Keep this
// short: it is a security control (permissions, IP allowlist), not a
// read-through cache for inert data, so a stale hit has real consequences.
const apiKeyCacheTTL = 10 * time.Second

// APIKeyAuthenticator authenticates SDP_-prefixed bearer tokens and caches
// validated keys - keyed by "<tenant ID>:<API key ID>", never by the raw
// secret and never by ID alone - so most requests avoid a DB round trip.
// Tenant-scoping the cache key prevents a raw key that is only valid for one
// tenant's schema from being served out of a cache entry warmed by a
// different tenant's context: the request's tenant comes from the
// attacker-controlled SDP-Tenant-Name header, so without this scoping a
// replayed key could ride another tenant's cached validation and bypass the
// schema-scoped DB lookup that is the sole mechanism binding a key to its
// tenant. Callers that mutate an API key's permissions, allowed IPs, or
// existence (update/delete) MUST call Invalidate(ctx, id) as part of that
// operation, or the cache can keep authorizing requests against the stale,
// pre-change permission set.
type APIKeyAuthenticator struct {
	model *data.APIKeyModel
	cache *ristretto.Cache
}

// NewAPIKeyAuthenticator builds an APIKeyAuthenticator backed by model.
func NewAPIKeyAuthenticator(model *data.APIKeyModel) *APIKeyAuthenticator {
	cache, err := ristretto.NewCache(&ristretto.Config{
		NumCounters: 10_000,
		MaxCost:     1_000,
		BufferItems: 64,
	})
	if err != nil {
		log.Errorf("Failed to create API key cache: %v", err)
		return &APIKeyAuthenticator{model: model}
	}

	cache.Wait()

	return &APIKeyAuthenticator{
		model: model,
		cache: cache,
	}
}

// cacheKeyFor builds the tenant-scoped cache key for the API key with the
// given ID, using the tenant resolved from ctx. ok is false (and key empty)
// when the tenant can't be resolved, in which case the cache must not be
// consulted at all - see validate for why.
func cacheKeyFor(ctx context.Context, id string) (key string, ok bool) {
	tenant, err := sdpcontext.GetTenantFromContext(ctx)
	if err != nil || tenant == nil || tenant.ID == "" {
		return "", false
	}
	return tenant.ID + ":" + id, true
}

// Invalidate evicts any cached validation result for the API key with the
// given ID, scoped to the tenant resolved from ctx (the same tenant the
// request that is updating/deleting the key is itself running under). It
// must be called whenever that key's permissions or allowed_ips are updated,
// or when the key is deleted, so the very next request using it is forced to
// re-fetch current authorization data from the DB instead of serving a stale
// cache hit.
func (a *APIKeyAuthenticator) Invalidate(ctx context.Context, id string) {
	if a == nil || a.cache == nil {
		return
	}
	if cacheKey, ok := cacheKeyFor(ctx, id); ok {
		a.cache.Del(cacheKey)
	}
}

func (a *APIKeyAuthenticator) validate(ctx context.Context, rawKey string) (*data.APIKey, error) {
	// The cache is keyed by "<tenant ID>:<API key ID>" rather than the raw
	// secret:
	//  - Tenant-scoping closes a cross-tenant cache-poisoning hole (see the
	//    type doc above): without it, a key cached while serving tenant A
	//    could be replayed under tenant B's name and served straight out of
	//    cache, bypassing the schema-scoped DB lookup that binds a key to
	//    its tenant.
	//  - Keying on the ID (not the secret) is what lets the /api-keys/{id}
	//    update/delete handlers evict exactly this entry: the raw secret is
	//    never persisted after creation, so those handlers have no way to
	//    derive it, only the ID.
	// The secret is still verified against the cached hash on every request
	// (cache hit or not), so a cache hit never skips authentication - it
	// only skips the DB round trip.
	id, secret, parseErr := data.ParseRawAPIKey(rawKey)

	var cacheKey string
	cacheable := false
	if parseErr == nil {
		cacheKey, cacheable = cacheKeyFor(ctx, id)
	}

	if a.cache == nil || !cacheable {
		apiKey, err := a.model.ValidateRawKeyAndUpdateLastUsed(ctx, rawKey)
		if err != nil {
			return nil, fmt.Errorf("validating API key (cacheless): %w", err)
		}
		return apiKey, nil
	}

	if cached, found := a.cache.Get(cacheKey); found {
		if apiKey, ok := cached.(*data.APIKey); ok &&
			!apiKey.IsExpired() &&
			apiKey.VerifySecret(secret) {
			return apiKey, nil
		}
		a.cache.Del(cacheKey)
	}

	apiKey, err := a.model.ValidateRawKeyAndUpdateLastUsed(ctx, rawKey)
	if err != nil {
		return nil, fmt.Errorf("validating API key: %w", err)
	}

	if !apiKey.IsExpired() {
		a.cache.SetWithTTL(cacheKey, apiKey, 1, apiKeyCacheTTL)
	}

	return apiKey, nil
}

func extractToken(r *http.Request) string {
	auth := r.Header.Get("Authorization")
	if parts := strings.Split(auth, " "); len(parts) == 2 {
		return parts[1]
	}
	return auth
}

func extractClientIP(r *http.Request) string {
	// Check proxy headers first
	for _, header := range []string{"X-Forwarded-For", "X-Real-IP"} {
		if ip := r.Header.Get(header); ip != "" {
			if comma := strings.Index(ip, ","); comma > 0 {
				ip = ip[:comma]
			}
			return strings.TrimSpace(ip)
		}
	}

	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil || host == "" {
		return r.RemoteAddr
	}
	return host
}

// Middleware first checks for an SDP_ key, then falls back to JWT.
func (a *APIKeyAuthenticator) Middleware(jwtAuth func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			token := extractToken(r)

			if !strings.HasPrefix(token, data.APIKeyPrefix) {
				jwtAuth(next).ServeHTTP(w, r)
				return
			}

			apiKey, err := a.validate(r.Context(), token)
			if err != nil {
				httperror.Unauthorized("Invalid API key", nil, nil).Render(w)
				return
			}

			if clientIP := extractClientIP(r); !apiKey.IsAllowedIP(clientIP) {
				httperror.Forbidden("IP not allowed", nil, nil).Render(w)
				return
			}

			// Set API key context
			ctx := r.Context()
			ctx = sdpcontext.SetAPIKeyInContext(ctx, apiKey)
			ctx = sdpcontext.SetUserIDInContext(ctx, apiKey.CreatedBy)
			ctx = log.Set(ctx, log.Ctx(ctx).WithField("user_id", apiKey.CreatedBy))

			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

// APIKeyOrJWTAuthenticate builds a one-off APIKeyAuthenticator and returns its
// middleware. Prefer constructing an APIKeyAuthenticator once (via
// NewAPIKeyAuthenticator) and sharing it with whatever also needs to call
// Invalidate (e.g. the API key management handlers) - this helper is kept for
// callers (and tests) that don't need to invalidate the cache themselves.
func APIKeyOrJWTAuthenticate(apiKeyModel *data.APIKeyModel, jwtAuth func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return NewAPIKeyAuthenticator(apiKeyModel).Middleware(jwtAuth)
}

// RequirePermission ensures the caller has the given APIKeyPermission or (if no APIKey in context) passes through to the next role-check.
func RequirePermission(perm data.APIKeyPermission, jwtCheck func(http.Handler) http.Handler) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			// --- API key path ---
			if apiKey, err := sdpcontext.GetAPIKeyFromContext(r.Context()); err == nil {
				if !apiKey.HasPermission(perm) {
					httperror.Forbidden("Insufficient API key permissions", nil, nil).Render(w)
					return
				}
				next.ServeHTTP(w, r)
				return
			}
			// --- JWT path: delegate ---
			jwtCheck(next).ServeHTTP(w, r)
		})
	}
}

