const (
	TenantHeaderKey string = "SDP-Tenant-Name"
)

// RecoverHandler is a middleware that recovers from panics and logs the error.
func RecoverHandler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
		defer func() {
			r := recover()
			if r == nil {
				return
			}
			err, ok := r.(error)
			if !ok {
				err = fmt.Errorf("panic: %v", r)
			}

			// No need to recover when the client has disconnected:
			if errors.Is(err, http.ErrAbortHandler) {
				panic(err)
			}

			ctx := req.Context()
			log.Ctx(ctx).WithStack(err).Error(err)
			httperror.InternalError(ctx, "", err, nil).WithErrorCode(httperror.Code500_0).Render(rw)
		}()

		next.ServeHTTP(rw, req)
	})
}

// MetricsRequestHandler is a middleware that monitors http requests, and export the data
// to the metrics server
func MetricsRequestHandler(monitorService monitor.MonitorServiceInterface) func(next http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			mw := middleware.NewWrapResponseWriter(rw, req.ProtoMajor)
			then := time.Now()
			next.ServeHTTP(mw, req)

			duration := time.Since(then)

			labels := monitor.HTTPRequestLabels{
				Status: fmt.Sprintf("%d", mw.Status()),
				Route:  utils.GetRoutePattern(req),
				Method: req.Method,
				CommonLabels: monitor.CommonLabels{
					TenantName: sdpcontext.MustGetTenantNameFromContext(req.Context()),
				},
			}

			if err := monitorService.MonitorHTTPRequestDuration(duration, labels); err != nil {
				log.Ctx(req.Context()).Errorf("Error trying to monitor request time: %s", err)
			}
		})
	}
}

// AuthenticateMiddleware is a middleware that validates the Authorization header for
// authenticated endpoints.
func AuthenticateMiddleware(authManager auth.AuthManager, tenantManager tenant.ManagerInterface) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			authHeader := req.Header.Get("Authorization")
			if authHeader == "" {
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			authHeaderParts := strings.Split(authHeader, " ")
			if len(authHeaderParts) != 2 {
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			ctx := req.Context()
			token := authHeaderParts[1]
			userID, err := authManager.GetUserID(ctx, token)
			if err != nil {
				if !errors.Is(err, auth.ErrInvalidToken) && !errors.Is(err, auth.ErrUserNotFound) {
					err = fmt.Errorf("error validating auth token: %w", err)
					log.Ctx(ctx).Error(err)
				}
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			// Add the token to the request context
			ctx = sdpcontext.SetTokenInContext(ctx, token)
			ctx = sdpcontext.SetUserIDInContext(ctx, userID)

			// Attempt fetching tenant ID from token
			tenantID, err := authManager.GetTenantID(ctx, token)
			if err == nil && tenantID != "" {
				currentTenant, tenantErr := tenantManager.GetTenantByID(ctx, tenantID)
				if tenantErr == nil && currentTenant != nil {
					ctx = sdpcontext.SetTenantInContext(ctx, currentTenant)
				}
			}

			// Add the user ID to the request context logger
			ctx = log.Set(ctx, log.Ctx(ctx).WithField("user_id", userID))

			req = req.WithContext(ctx)

			next.ServeHTTP(rw, req)
		})
	}
}

// AnyRoleMiddleware validates if the user has at least one of the required roles to request
// the current endpoint.
func AnyRoleMiddleware(authManager auth.AuthManager, requiredRoles ...data.UserRole) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			ctx := req.Context()

			token, err := sdpcontext.GetTokenFromContext(ctx)
			if err != nil {
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			// Accessible by all users
			if len(requiredRoles) == 0 {
				next.ServeHTTP(rw, req)
				return
			}

			hasAnyRoles, err := authManager.AnyRolesInTokenUser(ctx, token, data.FromUserRoleArrayToStringArray(requiredRoles))
			if err != nil {
				if errors.Is(err, auth.ErrInvalidToken) || errors.Is(err, auth.ErrUserNotFound) {
					httperror.Unauthorized("", nil, nil).Render(rw)
				} else {
					httperror.InternalError(ctx, "", err, nil).Render(rw)
				}
				return
			}

			if !hasAnyRoles {
				httperror.Forbidden("", nil, nil).Render(rw)
				return
			}

			next.ServeHTTP(rw, req)
		})
	}
}

func CorsMiddleware(corsAllowedOrigins []string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		cors := cors.New(cors.Options{
			AllowedOrigins: corsAllowedOrigins,
			AllowedHeaders: []string{"*"},
			AllowedMethods: []string{"GET", "PUT", "POST", "PATCH", "DELETE", "HEAD", "OPTIONS"},
		})

		return cors.Handler(next)
	}
}

type cspItem struct {
	ContentType string
	Policy      []string
}

func (c cspItem) String() string {
	return fmt.Sprintf("%s %s;", c.ContentType, strings.Join(c.Policy, " "))
}

// LoggingMiddleware is a middleware that logs requests to the logger.
func LoggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
		mw := mutil.WrapWriter(rw)

		reqCtx := req.Context()
		logFields := log.F{
			"method": req.Method,
			"path":   req.URL.String(),
			"req":    middleware.GetReqID(reqCtx),
		}
		logCtx := log.Set(reqCtx, log.Ctx(reqCtx).WithFields(logFields))

		ctxTenant, err := sdpcontext.GetTenantFromContext(reqCtx)
		if err != nil {
			// Log for auditing purposes when we cannot derive the tenant from the context in the case of
			// tenant-unaware endpoints
			log.Ctx(logCtx).Debug("tenant cannot be derived from context")
		}
		if ctxTenant != nil {
			logFields["tenant_name"] = ctxTenant.Name
			logFields["tenant_id"] = ctxTenant.ID
			logCtx = log.Set(reqCtx, log.Ctx(reqCtx).WithFields(logFields))
		}

		req = req.WithContext(logCtx)

		logRequestStart(req)
		started := time.Now()

		next.ServeHTTP(mw, req)
		ended := time.Since(started)
		logRequestEnd(req, mw, ended)
	})
}

func logRequestStart(req *http.Request) {
	l := log.Ctx(req.Context()).WithFields(
		log.F{
			"subsys":    "http",
			"ip":        req.RemoteAddr,
			"host":      req.Host,
			"useragent": req.Header.Get("User-Agent"),
		},
	)

	l.Info("starting request")
}

func logRequestEnd(req *http.Request, mw mutil.WriterProxy, duration time.Duration) {
	l := log.Ctx(req.Context()).WithFields(log.F{
		"subsys":   "http",
		"status":   mw.Status(),
		"bytes":    mw.BytesWritten(),
		"duration": duration,
	})
	if routeContext := chi.RouteContext(req.Context()); routeContext != nil {
		l = l.WithField("route", routeContext.RoutePattern())
	}

	l.Info("finished request")
}

// CSPMiddleware is the middleware that sets the content security policy, restricting content to only be accessed
// from specified sources in the header.
func CSPMiddleware() func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			selfSrc := "'self'"
			recaptchaSrc := "https://www.google.com/recaptcha/"
			ipapiSrc := "https://ipapi.co/json"
			cspItems := []cspItem{
				{"script-src", []string{selfSrc, recaptchaSrc, "https://www.gstatic.com/recaptcha/"}},
				{"style-src", []string{selfSrc, recaptchaSrc, "https://fonts.googleapis.com/css2", "'unsafe-inline'"}},
				{"connect-src", []string{selfSrc, recaptchaSrc, ipapiSrc}},
				{"font-src", []string{selfSrc, "https://fonts.gstatic.com"}},
				{"default-src", []string{selfSrc}},

				{"frame-src", []string{selfSrc, recaptchaSrc}},
				{"frame-ancestors", []string{selfSrc}},

				{"form-action", []string{selfSrc}},
			}
			cspStr := ""
			for _, item := range cspItems {
				cspStr += fmt.Sprintf("%v", item)
			}

			rw.Header().Set("Content-Security-Policy", cspStr)
			next.ServeHTTP(rw, req)
		})
	}
}

// ResolveTenantFromRequestMiddleware is a middleware that injects the tenant into the request context, if it can be found in
// the request HEADER, or the hostname prefix.
func ResolveTenantFromRequestMiddleware(tenantManager tenant.ManagerInterface, singleTenantMode bool) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			ctx := req.Context()

			var currentTenant *schema.Tenant
			if singleTenantMode {
				var err error
				currentTenant, err = tenantManager.GetDefault(ctx)
				if err != nil {
					switch {
					case errors.Is(err, tenant.ErrTenantDoesNotExist):
						// Log warning and allow the request to continue without a tenant.
						log.Ctx(ctx).Warnf(
							"No default tenant configured: %v. "+
								"use POST /default-tenant to set the default tenant.",
							err,
						)
						next.ServeHTTP(rw, req)
						return
					case errors.Is(err, tenant.ErrTooManyDefaultTenants):
						httperror.InternalError(ctx, "Too many default tenants configured", err, nil).Render(rw)
					default:
						httperror.InternalError(ctx, "", fmt.Errorf("error getting default tenant: %w", err), nil).Render(rw)
					}
					return
				}
			} else {
				// Attempt fetching tenant name from request
				tenantName, err := extractTenantNameFromRequest(req)
				if err != nil {
					if errors.Is(err, utils.ErrHostnameIsIPAddress) {
						log.Ctx(ctx).Debug("hostname is an IP address, skipping tenant resolution")
					} else if !errors.Is(err, utils.ErrTenantNameNotFound) {
						log.Ctx(ctx).Debugf("could not extract tenant name from request: %v", err)
					}
				} else if tenantName != "" {
					currentTenant, err = tenantManager.GetTenantByName(ctx, tenantName)
					if err != nil {
						log.Ctx(ctx).Warnf("could not find tenant with name %s: %v", tenantName, err)
					}
				}
			}

			if currentTenant != nil {
				ctx = sdpcontext.SetTenantInContext(ctx, currentTenant)
				next.ServeHTTP(rw, req.WithContext(ctx))
			} else {
				next.ServeHTTP(rw, req)
			}
		})
	}
}

// EnsureTenantMiddleware is a middleware that ensures the tenant is in the request context.
func EnsureTenantMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
		ctx := req.Context()

		if _, err := sdpcontext.GetTenantFromContext(ctx); err != nil {
			httperror.BadRequest("Tenant not found in context", err, nil).Render(rw)
			return
		}

		next.ServeHTTP(rw, req)
	})
}

func BasicAuthMiddleware(adminAccount, adminAPIKey string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			ctx := req.Context()

			if adminAccount == "" || adminAPIKey == "" {
				httperror.InternalError(ctx, "Admin account and API key are not set", nil, nil).Render(rw)
				return
			}

			accountUserName, apiKey, ok := req.BasicAuth()
			if !ok {
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			// Using constant time comparison to avoid timing attacks
			if accountUserName != adminAccount || subtle.ConstantTimeCompare([]byte(apiKey), []byte(adminAPIKey)) != 1 {
				httperror.Unauthorized("", nil, nil).Render(rw)
				return
			}

			log.Ctx(ctx).Infof("[AdminAuth] - Admin authenticated with account %s", adminAccount)
			next.ServeHTTP(rw, req)
		})
	}
}

// DefaultMaxRequestBodySize is the default maximum request body size (10 MB) applied globally (CWE-770).
const DefaultMaxRequestBodySize int64 = 10 * 1024 * 1024

// MaxBodySize is a middleware that limits the size of the request body using http.MaxBytesReader (CWE-770).
func MaxBodySize(maxBytes int64) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(rw http.ResponseWriter, req *http.Request) {
			req.Body = http.MaxBytesReader(rw, req.Body, maxBytes)
			next.ServeHTTP(rw, req)
		})
	}
}

// extractTenantNameFromRequest attempts to extract the tenant name from the request HEADER[tenantHeaderKey] or the hostname prefix.
func extractTenantNameFromRequest(r *http.Request) (string, error) {
	// 1. Try extracting from the TenantHeaderKey header first
	tenantName := r.Header.Get(TenantHeaderKey)
	if tenantName != "" {
		return tenantName, nil
	}

	// 2. If header is blank, extract from the hostname prefix
	tenantName, err := utils.ExtractTenantNameFromHostName(r.Host)
	if err != nil {
		return "", fmt.Errorf("extracting tenant name from hostname: %w", err)
	}
	return tenantName, nil
}

package auth

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/stellar/stellar-disbursement-platform-backend/db"
)

var ErrInvalidToken = errors.New("invalid token")

type AuthManager interface {
	Authenticate(ctx context.Context, email, pass string) (string, error)
	// RefreshToken generates a new token if the current token is going to expire in less than `tokenRefreshWindow` minutes.
	// Otherwise, it returns the same token.
	RefreshToken(ctx context.Context, tokenString string) (string, error)
	ValidateToken(ctx context.Context, tokenString string) (bool, error)
	AllRolesInTokenUser(ctx context.Context, tokenString string, roleNames []string) (bool, error)
	AnyRolesInTokenUser(ctx context.Context, tokenString string, roleNames []string) (bool, error)
	CreateUser(ctx context.Context, user *User, password string) (*User, error)
	UpdateUser(ctx context.Context, tokenString, firstName, lastName, email, password string) error
	ForgotPassword(ctx context.Context, sqlExec db.SQLExecuter, email string) (string, error)
	ResetPassword(ctx context.Context, tokenString, password string) error
	UpdatePassword(ctx context.Context, token, currentPassword, newPassword string) error
	GetUser(ctx context.Context, tokenString string) (*User, error)
	GetUsersByID(ctx context.Context, userIDs []string, activeOnly bool) ([]*User, error)
	GetUserByID(ctx context.Context, userID string) (*User, error)
	GetUserID(ctx context.Context, tokenString string) (string, error)
	GetTenantID(ctx context.Context, tokenString string) (string, error)
	GetAllUsers(ctx context.Context, tokenString string) ([]User, error)
	UpdateUserRoles(ctx context.Context, tokenString, userID string, roles []string) error
	DeactivateUser(ctx context.Context, tokenString, userID string) error
	ActivateUser(ctx context.Context, tokenString, userID string) error
	ExpirationTimeInMinutes() time.Duration
	MFADeviceRemembered(ctx context.Context, deviceID, userID string) (bool, error)
	GetMFACode(ctx context.Context, deviceID, userID string) (string, error)
	AuthenticateMFA(ctx context.Context, deviceID, code string, rememberMe bool) (string, error)
}

func (am *defaultAuthManager) Authenticate(ctx context.Context, email, pass string) (string, error) {
	user, err := am.authenticator.ValidateCredentials(ctx, email, pass)
	if err != nil {
		return "", fmt.Errorf("validating credentials: %w", err)
	}

	return am.generateToken(ctx, user)
}

func (am *defaultAuthManager) generateToken(ctx context.Context, user *User) (string, error) {
	roles, err := am.roleManager.GetUserRoles(ctx, user)
	if err != nil {
		return "", fmt.Errorf("error getting user roles: %w", err)
	}

	user.Roles = roles

	expiresAt := time.Now().Add(am.expirationTimeInMinutes)

	tokenString, err := am.jwtManager.GenerateToken(ctx, user, expiresAt)
	if err != nil {
		return "", fmt.Errorf("generating token: %w", err)
	}

	return tokenString, nil
}

func (am *defaultAuthManager) RefreshToken(ctx context.Context, tokenString string) (string, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return "", fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return "", ErrInvalidToken
	}

	// TODO: find a way to not refresh the same token
	// more than once - perhaps create a table and store invalid tokens
	expiresAt := time.Now().Add(am.expirationTimeInMinutes)
	tokenString, err = am.jwtManager.RefreshToken(ctx, tokenString, expiresAt)
	if err != nil {
		return "", fmt.Errorf("generating new refreshed token: %w", err)
	}

	return tokenString, nil
}

func (am *defaultAuthManager) ValidateToken(ctx context.Context, tokenString string) (bool, error) {
	isValid, err := am.jwtManager.ValidateToken(ctx, tokenString)
	if err != nil {
		return false, fmt.Errorf("validating token: %w", err)
	}

	return isValid, nil
}

// AllRolesInTokenUser checks whether the user's token has all the roles passed by parameter.
func (am *defaultAuthManager) AllRolesInTokenUser(ctx context.Context, tokenString string, roleNames []string) (bool, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return false, fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return false, ErrInvalidToken
	}

	user, err := am.jwtManager.GetUserFromToken(ctx, tokenString)
	if err != nil {
		return false, fmt.Errorf("error getting user from token: %w", err)
	}

	hasAllRoles, err := am.roleManager.HasAllRoles(ctx, user, roleNames)
	if err != nil {
		return false, fmt.Errorf("error validating user roles: %w", err)
	}

	return hasAllRoles, nil
}

// AnyRolesInTokenUser checks whether the user's token has one or more the roles passed by parameter.
func (am *defaultAuthManager) AnyRolesInTokenUser(ctx context.Context, tokenString string, roleNames []string) (bool, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return false, fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return false, ErrInvalidToken
	}

	user, err := am.jwtManager.GetUserFromToken(ctx, tokenString)
	if err != nil {
		return false, fmt.Errorf("error getting user from token: %w", err)
	}

	hasAnyRoles, err := am.roleManager.HasAnyRoles(ctx, user, roleNames)
	if err != nil {
		return false, fmt.Errorf("error validating user roles: %w", err)
	}

	return hasAnyRoles, nil
}

// CreateUser creates a new user using Authenticator's CreateUser method.
func (am *defaultAuthManager) CreateUser(ctx context.Context, user *User, password string) (*User, error) {
	user, err := am.authenticator.CreateUser(ctx, user, password)
	if err != nil {
		return nil, fmt.Errorf("creating user: %w", err)
	}

	return user, nil
}

func (am *defaultAuthManager) UpdateUser(ctx context.Context, tokenString, firstName, lastName, email, password string) error {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return ErrInvalidToken
	}

	user, err := am.jwtManager.GetUserFromToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("getting user from token: %w", err)
	}

	err = am.authenticator.UpdateUser(ctx, user.ID, firstName, lastName, email, password)
	if err != nil {
		return fmt.Errorf("error updating user: %w", err)
	}

	// If the password changed, revoke every remembered device for the user.
	if password != "" {
		if err := am.mfaManager.ForgetAllDevices(ctx, user.ID); err != nil {
			return fmt.Errorf("error forgetting devices after updating user ID %s: %w", user.ID, err)
		}
	}

	return nil
}

// ForgotPassword handles the generation of a new password reset token for the user to set a new password.
func (am *defaultAuthManager) ForgotPassword(ctx context.Context, sqlExec db.SQLExecuter, email string) (string, error) {
	resetToken, err := am.authenticator.ForgotPassword(ctx, sqlExec, email)
	if err != nil {
		if errors.Is(err, ErrUserNotFound) {
			return "", fmt.Errorf("user not found in auth forgot password: %w", err)
		}
		return "", fmt.Errorf("calling authenticator's ForgotPassword: %w", err)
	}

	return resetToken, nil
}

// ResetPassword sets the user's new password using a valid reset token generated in the ForgotPassword flow.
func (am *defaultAuthManager) ResetPassword(ctx context.Context, resetToken, newPassword string) error {
	userID, err := am.authenticator.ResetPassword(ctx, resetToken, newPassword)
	if err != nil {
		if errors.Is(err, ErrInvalidResetPasswordToken) {
			return fmt.Errorf("invalid token in auth reset password: %w", err)
		}
		return fmt.Errorf("error on reset password: %w", err)
	}

	// The password changed, so revoke every remembered device for the user.
	if err := am.mfaManager.ForgetAllDevices(ctx, userID); err != nil {
		return fmt.Errorf("error forgetting devices after reset password for user ID %s: %w", userID, err)
	}

	return nil
}

func (am *defaultAuthManager) UpdatePassword(ctx context.Context, tokenString, currentPassword, newPassword string) error {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return ErrInvalidToken
	}

	user, err := am.jwtManager.GetUserFromToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("getting user from token: %w", err)
	}

	err = am.authenticator.UpdatePassword(ctx, user, currentPassword, newPassword)
	if err != nil {
		return fmt.Errorf("updating password: %w", err)
	}

	// The password changed, so revoke every remembered device for the user.
	if err := am.mfaManager.ForgetAllDevices(ctx, user.ID); err != nil {
		return fmt.Errorf("error forgetting devices after updating password for user ID %s: %w", user.ID, err)
	}

	return nil
}

func (am *defaultAuthManager) ActivateUser(ctx context.Context, tokenString, userID string) error {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return ErrInvalidToken
	}

	err = am.authenticator.ActivateUser(ctx, userID)
	if err != nil {
		return fmt.Errorf("error activating user ID %s: %w", userID, err)
	}

	return nil
}

func (am *defaultAuthManager) DeactivateUser(ctx context.Context, tokenString, userID string) error {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return ErrInvalidToken
	}

	err = am.authenticator.DeactivateUser(ctx, userID)
	if err != nil {
		return fmt.Errorf("error deactivating user ID %s: %w", userID, err)
	}

	return nil
}

func (am *defaultAuthManager) UpdateUserRoles(ctx context.Context, tokenString, userID string, roles []string) error {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return ErrInvalidToken
	}

	// TODO: pass all fields of the user
	err = am.roleManager.UpdateRoles(ctx, &User{ID: userID}, roles)
	if err != nil {
		return fmt.Errorf("error updating user roles: %w", err)
	}

	return nil
}

func (am *defaultAuthManager) GetAllUsers(ctx context.Context, tokenString string) ([]User, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return nil, fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return nil, ErrInvalidToken
	}

	users, err := am.authenticator.GetAllUsers(ctx)
	if err != nil {
		return nil, fmt.Errorf("error getting all users: %w", err)
	}

	return users, nil
}

func (am *defaultAuthManager) getUserFromToken(ctx context.Context, tokenString string) (*User, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return nil, fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return nil, ErrInvalidToken
	}

	user, err := am.jwtManager.GetUserFromToken(ctx, tokenString)
	if err != nil {
		return nil, fmt.Errorf("getting user from token: %w", err)
	}

	return user, nil
}

func (am *defaultAuthManager) GetUsersByID(ctx context.Context, userIDs []string, activeOnly bool) ([]*User, error) {
	users, err := am.authenticator.GetUsers(ctx, userIDs, activeOnly)
	if err != nil {
		return nil, fmt.Errorf("getting user with IDs: %w", err)
	}

	return users, nil
}

func (am *defaultAuthManager) GetUserByID(ctx context.Context, userID string) (*User, error) {
	user, err := am.authenticator.GetUser(ctx, userID)
	if err != nil {
		return nil, ErrUserNotFound
	}

	return user, nil
}

func (am *defaultAuthManager) GetTenantID(ctx context.Context, tokenString string) (string, error) {
	isValid, err := am.ValidateToken(ctx, tokenString)
	if err != nil {
		return "", fmt.Errorf("validating token: %w", err)
	}

	if !isValid {
		return "", ErrInvalidToken
	}

	tenantID, err := am.jwtManager.GetTenantIDFromToken(ctx, tokenString)
	if err != nil {
		return "", fmt.Errorf("getting tenant ID from token: %w", err)
	}

	return tenantID, nil
}

func (am *defaultAuthManager) GetUserID(ctx context.Context, tokenString string) (string, error) {
	tokenUser, err := am.getUserFromToken(ctx, tokenString)
	if err != nil {
		return "", err
	}

	return tokenUser.ID, nil
}

func (am *defaultAuthManager) GetUser(ctx context.Context, tokenString string) (*User, error) {
	tokenUser, err := am.getUserFromToken(ctx, tokenString)
	if err != nil {
		return nil, fmt.Errorf("getting user from token: %w", err)
	}

	// We get the user latest state
	user, err := am.authenticator.GetUser(ctx, tokenUser.ID)
	if err != nil {
		return nil, fmt.Errorf("getting user ID %s: %w", tokenUser.ID, err)
	}

	roles, err := am.roleManager.GetUserRoles(ctx, user)
	if err != nil {
		return nil, fmt.Errorf("getting user ID %s roles: %w", tokenUser.ID, err)
	}

	user.Roles = roles

	return user, nil
}

func (am *defaultAuthManager) ExpirationTimeInMinutes() time.Duration {
	return am.expirationTimeInMinutes
}

//nolint:wrapcheck // This is a wrapper method
func (am *defaultAuthManager) MFADeviceRemembered(ctx context.Context, deviceID, userID string) (bool, error) {
	return am.mfaManager.MFADeviceRemembered(ctx, deviceID, userID)
}

//nolint:wrapcheck // This is a wrapper method
func (am *defaultAuthManager) GetMFACode(ctx context.Context, deviceID, userID string) (string, error) {
	return am.mfaManager.GenerateMFACode(ctx, deviceID, userID)
}

func (am *defaultAuthManager) AuthenticateMFA(ctx context.Context, deviceID, code string, rememberMe bool) (string, error) {
	userID, err := am.mfaManager.ValidateMFACode(ctx, deviceID, code)
	if err != nil {
		return "", fmt.Errorf("error validating MFA code: %w", err)
	}

	if rememberMe {
		if err = am.mfaManager.RememberDevice(ctx, deviceID, userID); err != nil {
			return "", fmt.Errorf("error remembering device ID %s: %w", deviceID, err)
		}
	}

	user, err := am.authenticator.GetUser(ctx, userID)
	if err != nil {
		return "", fmt.Errorf("error getting user ID %s: %w", userID, err)
	}

	return am.generateToken(ctx, user)
}

