// ReceiverInScopeCondition is the single definition of "this caller may reach this receiver": the
// account it was created under, or any account that has paid them. Reads filter with it and writes
// gate on it, so the two can never drift. Pair it with ReceiverInScopeArgs.
const ReceiverInScopeCondition = `(
	r.source_wallet_id = ANY(?)
	OR EXISTS (SELECT 1 FROM payments pw WHERE pw.receiver_id = r.id AND pw.source_wallet_id = ANY(?))
)`

// ReceiverInScopeArgs returns the arguments ReceiverInScopeCondition binds, in order.
func ReceiverInScopeArgs(walletIDs []string) []any {
	return []any{pq.Array(walletIDs), pq.Array(walletIDs)}
}

type ReceiverModel struct{}

type ReceiverInsert struct {
	PhoneNumber    *string `db:"phone_number"`
	Email          *string `db:"email"`
	ExternalID     *string `db:"external_id"`
	SourceWalletID string  `db:"source_wallet_id"`
}

type ReceiverUpdate ReceiverInsert

func (ru ReceiverUpdate) IsEmpty() bool {
	return ru.Email == nil && ru.ExternalID == nil && ru.PhoneNumber == nil
}

func (ru ReceiverUpdate) Validate() error {
	if ru.IsEmpty() {
		return fmt.Errorf("no values provided to update receiver")
	}

	if ru.Email != nil {
		if err := utils.ValidateEmail(*ru.Email); err != nil {
			return fmt.Errorf("validating email: %w", err)
		}
	}

	if ru.PhoneNumber != nil {
		if err := utils.ValidatePhoneNumber(*ru.PhoneNumber); err != nil {
			return fmt.Errorf("validating phone number: %w", err)
		}
	}

	return nil
}

type ReceivedAmounts []Amount

// Scan implements the sql.Scanner interface.
func (ra *ReceivedAmounts) Scan(src interface{}) error {
	var receivedAmounts sql.NullString
	if err := (&receivedAmounts).Scan(src); err != nil {
		return fmt.Errorf("scanning status history value: %w", err)
	}

	if receivedAmounts.Valid {
		var shEntry []Amount
		err := json.Unmarshal([]byte(receivedAmounts.String), &shEntry)
		if err != nil {
			return fmt.Errorf("unmarshaling status_history column: %w", err)
		}

		*ra = shEntry
	}

	return nil
}

// IsInScope reports whether the receiver is reachable from any of the given wallets. A nil scope is
// the Owner's tenant-wide view and always passes.
func (r *ReceiverModel) IsInScope(ctx context.Context, sqlExec db.SQLExecuter, receiverID string, scope []string) (bool, error) {
	if scope == nil {
		return true, nil
	}

	query := sqlExec.Rebind(`SELECT ` + ReceiverInScopeCondition + ` FROM receivers r WHERE r.id = ?`)

	var inScope bool
	if err := sqlExec.GetContext(ctx, &inScope, query, append(ReceiverInScopeArgs(scope), receiverID)...); err != nil {
		// A receiver that does not exist is simply not reachable, so callers render it the same as one
		// they may not reach — the two must not be distinguishable.
		if errors.Is(err, sql.ErrNoRows) {
			return false, nil
		}
		return false, fmt.Errorf("checking receiver %q scope: %w", receiverID, err)
	}

	return inScope, nil
}

// InScopeIDs returns which of the given receivers are reachable from the given wallets, using the
// same definition as IsInScope. A nil scope is the Owner's tenant-wide view, so every id is returned.
func (r *ReceiverModel) InScopeIDs(ctx context.Context, sqlExec db.SQLExecuter, receiverIDs []string, scope []string) (map[string]struct{}, error) {
	inScope := make(map[string]struct{}, len(receiverIDs))
	if scope == nil {
		for _, id := range receiverIDs {
			inScope[id] = struct{}{}
		}
		return inScope, nil
	}

	query := sqlExec.Rebind(`
		SELECT r.id
		FROM receivers r
		WHERE r.id = ANY(?) AND ` + ReceiverInScopeCondition)

	var ids []string
	args := append([]any{pq.Array(receiverIDs)}, ReceiverInScopeArgs(scope)...)
	if err := sqlExec.SelectContext(ctx, &ids, query, args...); err != nil {
		return nil, fmt.Errorf("filtering receivers to wallet scope: %w", err)
	}
	for _, id := range ids {
		inScope[id] = struct{}{}
	}

	return inScope, nil
}

// HasNonTerminalPayments reports whether the receiver is still owed money on any payment.
func (r *ReceiverModel) HasNonTerminalPayments(ctx context.Context, sqlExec db.SQLExecuter, receiverID string) (bool, error) {
	const q = `
		SELECT EXISTS (
			SELECT 1
			  FROM payments
			 WHERE receiver_id = $1
			   AND status = ANY($2)
		)
	`

	var exists bool
	if err := sqlExec.GetContext(ctx, &exists, q, receiverID, pq.Array(PaymentNonTerminalStatuses())); err != nil {
		return false, fmt.Errorf("checking non-terminal payments for receiver %q: %w", receiverID, err)
	}

	return exists, nil
}

// Get returns a RECEIVER matching the given ID, with tenant-wide payment counters.
func (r *ReceiverModel) Get(ctx context.Context, sqlExec db.SQLExecuter, id string) (*Receiver, error) {
	return r.GetWithStatsScope(ctx, sqlExec, id, nil)
}

// GetWithStatsScope returns a RECEIVER matching the given ID, counting only payments made from the
// given distribution wallets. A nil scope leaves the counters tenant-wide.
func (r *ReceiverModel) GetWithStatsScope(ctx context.Context, sqlExec db.SQLExecuter, id string, statsScope []string) (*Receiver, error) {
	filters := map[FilterKey]interface{}{FilterKeyID: id}
	if statsScope != nil {
		filters[FilterKeyStatsSourceWalletIDs] = statsScope
	}

	receivers, err := r.GetAll(ctx, sqlExec, &QueryParams{Filters: filters}, QueryTypeSingle)
	if err != nil {
		return nil, fmt.Errorf("getting receiver by id: %w", err)
	}

	if len(receivers) == 0 {
		return nil, ErrRecordNotFound
	}

	return &receivers[0], nil
}

// Count returns the number of receivers matching the given query parameters.
func (r *ReceiverModel) Count(ctx context.Context, sqlExec db.SQLExecuter, queryParams *QueryParams) (int, error) {
	var count int
	const q = `
		SELECT
			COUNT(DISTINCT r.id)
		FROM receivers r
		LEFT JOIN receiver_wallets rw ON rw.receiver_id = r.id
	`
	query, params := newReceiverQuery(q, queryParams, sqlExec, QueryTypeSingle)

	err := sqlExec.GetContext(ctx, &count, query, params...)
	if err != nil {
		return 0, fmt.Errorf("counting payments: %w", err)
	}

	return count, nil
}

// GetAll returns all RECEIVERS matching the given query parameters.
func (r *ReceiverModel) GetAll(ctx context.Context, sqlExec db.SQLExecuter, queryParams *QueryParams, queryType QueryType) ([]Receiver, error) {
	receivers := []Receiver{}

	// The counters below must cover the same payments the caller can see, or a receiver's totals
	// contradict their payment list.
	statsScope, statsParams := receiverStatsScope(queryParams)

	query := `
		WITH receiver_stats AS (
			SELECT
				r.id as receiver_id,
				COUNT(p) as total_payments,
				COUNT(p) FILTER(WHERE p.status = 'SUCCESS') as successful_payments,
				COUNT(p) FILTER(WHERE p.status = 'FAILED') as failed_payments,
				COUNT(p) FILTER(WHERE p.status = 'CANCELED') as canceled_payments,
				COUNT(p) FILTER(WHERE p.status IN ('DRAFT', 'READY', 'PENDING', 'PAUSED')) as remaining_payments,
				a.code as asset_code,
				a.issuer as asset_issuer,
				COALESCE(SUM(p.amount) FILTER(WHERE p.asset_id = a.id AND p.status = 'SUCCESS'), '0') as received_amount
			FROM receivers r
			JOIN payments p ON r.id = p.receiver_id` + statsScope + `
			JOIN assets a ON a.id = p.asset_id
			GROUP BY (r.id, a.code, a.issuer)
		), receiver_stats_aggregate AS (
			SELECT
				rs.receiver_id,
				SUM(rs.total_payments) as total_payments,
				SUM(rs.successful_payments) as successful_payments,
				SUM(rs.failed_payments) as failed_payments,
				SUM(rs.canceled_payments) as canceled_payments,
				SUM(rs.remaining_payments) as remaining_payments,
				jsonb_agg(jsonb_build_object('asset_code', rs.asset_code, 'asset_issuer', rs.asset_issuer, 'received_amount', rs.received_amount::text)) as received_amounts
			FROM receiver_stats rs
			GROUP BY (rs.receiver_id)
		)
		SELECT DISTINCT
			` + ReceiverColumnNames("r", "") + `,
			COALESCE(rs.total_payments, 0) as total_payments,
			COALESCE(rs.successful_payments, 0) as successful_payments,
			COALESCE(rs.failed_payments, '0') as failed_payments,
			COALESCE(rs.canceled_payments, '0') as canceled_payments,
			COALESCE(rs.remaining_payments, '0') as remaining_payments,
			COALESCE(rs.received_amounts, '[]') as received_amounts,
			COALESCE((
				SELECT COUNT(*)
				FROM receiver_wallets rw2
				WHERE rw2.receiver_id = r.id
				AND rw2.status = 'REGISTERED'
			), 0) as registered_wallets
		FROM receivers r
		LEFT JOIN receiver_wallets rw ON rw.receiver_id = r.id
		LEFT JOIN receiver_stats_aggregate rs ON rs.receiver_id = r.id
		`

	query, params := newReceiverQuery(query, queryParams, sqlExec, queryType, statsParams...)

	err := sqlExec.SelectContext(ctx, &receivers, query, params...)
	if err != nil {
		return nil, fmt.Errorf("querying receivers: %w", err)
	}

	return receivers, nil
}

// receiverStatsScope narrows the payment counters to the given distribution wallets, returning the
// join predicate and its parameter. An absent filter leaves the counters tenant-wide, which is what
// an Owner (and the "all accounts" view) should see.
func receiverStatsScope(queryParams *QueryParams) (string, []interface{}) {
	walletIDs, ok := queryParams.Filters[FilterKeyStatsSourceWalletIDs].([]string)
	if !ok {
		return "", nil
	}

	return " AND p.source_wallet_id = ANY(?)", []interface{}{pq.Array(walletIDs)}
}

// newReceiverQuery generates the full query and parameters for a receiver search query. baseParams
// belong to placeholders already present in baseQuery, and bind ahead of every condition added here.
func newReceiverQuery(baseQuery string, queryParams *QueryParams, sqlExec db.SQLExecuter, queryType QueryType, baseParams ...interface{}) (string, []interface{}) {
	qb := NewQueryBuilderWithParams(baseQuery, baseParams...)
	if queryParams.Filters[FilterKeyID] != nil {
		addArrayOrSingleCondition[string](qb, "r.id", queryParams.Filters[FilterKeyID])
	}
	if queryParams.Query != "" {
		q := "%" + queryParams.Query + "%"
		qb.AddCondition("(r.id ILIKE ? OR r.phone_number ILIKE ? OR r.email ILIKE ?)", q, q, q)
	}
	if queryParams.Filters[FilterKeyStatus] != nil {
		status := queryParams.Filters[FilterKeyStatus].(ReceiversWalletStatus)
		qb.AddCondition("rw.status = ?", status)
	}
	if queryParams.Filters[FilterKeyCreatedAtAfter] != nil {
		qb.AddCondition("r.created_at >= ?", queryParams.Filters[FilterKeyCreatedAtAfter])
	}
	if queryParams.Filters[FilterKeyCreatedAtBefore] != nil {
		qb.AddCondition("r.created_at <= ?", queryParams.Filters[FilterKeyCreatedAtBefore])
	}
	if walletIDs, ok := queryParams.Filters[FilterKeySourceWalletIDs].([]string); ok {
		// Additive: the account the receiver was created under, plus any account that has paid them.
		// Alias both sides — an unqualified source_wallet_id inside the subquery binds to payments.
		qb.AddCondition(ReceiverInScopeCondition, ReceiverInScopeArgs(walletIDs)...)
	}

	switch queryType {
	case QueryTypeSelectPaginated:
		qb.AddPagination(queryParams.Page, queryParams.PageLimit)
		qb.AddSorting(queryParams.SortBy, queryParams.SortOrder, "r")
	case QueryTypeSelectAll:
		qb.AddSorting(queryParams.SortBy, queryParams.SortOrder, "r")
	case QueryTypeSingle:
		// no need to sort or paginate.
	}

	query, params := qb.Build()
	return sqlExec.Rebind(query), params
}

type ReceiverIDs []string

// ParseReceiverIDs return the array of receivers IDs.
func (r *ReceiverModel) ParseReceiverIDs(receivers []Receiver) ReceiverIDs {
	receiverIds := make(ReceiverIDs, 0)

	for _, receiver := range receivers {
		receiverIds = append(receiverIds, receiver.ID)
	}

	return receiverIds
}

// Insert inserts a new receiver into the database.
func (r *ReceiverModel) Insert(ctx context.Context, sqlExec db.SQLExecuter, insert ReceiverInsert) (*Receiver, error) {
	query := `
		INSERT INTO receivers (
			phone_number,
			email,
			external_id,
			source_wallet_id
		) VALUES (
			$1,
			$2,
		    $3,
		    $4
		) RETURNING
			` + ReceiverColumnNames("", "")

	var receiver Receiver
	err := sqlExec.GetContext(ctx, &receiver, query, insert.PhoneNumber, insert.Email, insert.ExternalID, insert.SourceWalletID)
	if err != nil {
		var pqError *pq.Error
		if errors.As(err, &pqError) && pqError.Code == "23505" {
			switch pqError.Constraint {
			case "receiver_unique_email":
				return nil, ErrDuplicateEmail
			case "receiver_unique_phone_number":
				return nil, ErrDuplicatePhoneNumber
			}
		}
		return nil, fmt.Errorf("inserting receiver: %w", err)
	}

	return &receiver, nil
}

// Update updates the receiver Email and/or External ID.
func (r *ReceiverModel) Update(ctx context.Context, sqlExec db.SQLExecuter, ID string, receiverUpdate ReceiverUpdate) error {
	if err := receiverUpdate.Validate(); err != nil {
		return fmt.Errorf("validating receiver update: %w", err)
	}

	args := []interface{}{}
	fields := []string{}

	if receiverUpdate.PhoneNumber != nil {
		phoneNumber := *receiverUpdate.PhoneNumber
		fields = append(fields, "phone_number = ?")
		args = append(args, phoneNumber)
	}

	if receiverUpdate.Email != nil {
		email := *receiverUpdate.Email
		fields = append(fields, "email = ?")
		args = append(args, email)
	}

	if receiverUpdate.ExternalID != nil {
		externalID := *receiverUpdate.ExternalID
		fields = append(fields, "external_id = ?")
		args = append(args, externalID)
	}

	args = append(args, ID)

	query := `
		UPDATE
			receivers
		SET
			%s
		WHERE
			id = ?
	`

	query = sqlExec.Rebind(fmt.Sprintf(query, strings.Join(fields, ", ")))

	_, err := sqlExec.ExecContext(ctx, query, args...)
	if err != nil {
		var pqError *pq.Error
		if errors.As(err, &pqError) && pqError.Code == "23505" {
			switch pqError.Constraint {
			case "receiver_unique_email":
				return ErrDuplicateEmail
			case "receiver_unique_phone_number":
				return ErrDuplicatePhoneNumber
			}
		}
		return fmt.Errorf("updating receiver: %w", err)
	}

	return nil
}

// GetByContacts search for receivers by phone numbers and email.
func (r *ReceiverModel) GetByContacts(ctx context.Context, sqlExec db.SQLExecuter, contacts ...string) ([]*Receiver, error) {
	receivers := []*Receiver{}

	if len(contacts) == 0 {
		return receivers, nil
	}

	query := `
	SELECT
		` + ReceiverColumnNames("r", "") + `
	FROM receivers r
	WHERE r.phone_number = ANY($1) OR r.email = ANY($1)
	`
	err := sqlExec.SelectContext(ctx, &receivers, query, pq.Array(contacts))
	if err != nil {
		return nil, fmt.Errorf("fetching receivers by phone numbers or email: %w", err)
	}
	return receivers, nil
}

func (r *ReceiverModel) GetByWalletAddress(ctx context.Context, sqlExec db.SQLExecuter, walletAddress string) (*Receiver, error) {
	query := `
		SELECT DISTINCT
			` + ReceiverColumnNames("r", "") + `
		FROM 
			receivers r
			INNER JOIN receiver_wallets rw ON r.id = rw.receiver_id
		WHERE 
			rw.stellar_address = $1
			AND rw.status = $2
	`

	var receivers []Receiver
	err := sqlExec.SelectContext(ctx, &receivers, query, walletAddress, RegisteredReceiversWalletStatus)
	if err != nil {
		return nil, fmt.Errorf("querying receiver by wallet address %s: %w", walletAddress, err)
	}

	if len(receivers) == 0 {
		return nil, ErrRecordNotFound
	}

	if len(receivers) > 1 {
		return nil, fmt.Errorf("multiple receivers found with wallet address %s", walletAddress)
	}

	return &receivers[0], nil
}

// DeleteByContactInfo deletes a receiver by phone number or email. It also deletes the associated entries in other
// tables: messages, payments, receiver_verifications, receiver_wallets, receivers, disbursements,
// submitter_transactions.
func (r *ReceiverModel) DeleteByContactInfo(ctx context.Context, dbConnectionPool db.DBConnectionPool, contactInfo string) error {
	return db.RunInTransaction(ctx, dbConnectionPool, nil, func(dbTx db.DBTransaction) error {
		query := "SELECT id FROM receivers WHERE phone_number = $1 OR email = $1"
		var receiverID string

		err := dbTx.GetContext(ctx, &receiverID, query, contactInfo)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return ErrRecordNotFound
			}
			return fmt.Errorf("fetching receiver by contact info %s: %w", contactInfo, err)
		}

		type QueryWithParams struct {
			Query  string
			Params []interface{}
		}

		queries := []QueryWithParams{
			{"DELETE FROM messages WHERE receiver_id = $1", []interface{}{receiverID}},
			{"DELETE FROM receiver_verifications WHERE receiver_id = $1", []interface{}{receiverID}},
			{"DELETE FROM circle_transfer_requests WHERE payment_id IN (SELECT id FROM payments WHERE receiver_id = $1)", []interface{}{receiverID}},
			{"DELETE FROM circle_recipients WHERE receiver_wallet_id IN (SELECT id FROM receiver_wallets WHERE receiver_id = $1)", []interface{}{receiverID}},
			{"DELETE FROM payments WHERE receiver_id = $1", []interface{}{receiverID}},
			{"DELETE FROM receiver_wallets WHERE receiver_id = $1", []interface{}{receiverID}},
			{"DELETE FROM receivers WHERE id = $1", []interface{}{receiverID}},
			{"DELETE FROM disbursements WHERE id NOT IN (SELECT DISTINCT disbursement_id FROM payments)", nil},
		}

		for _, qwp := range queries {
			_, err = dbTx.ExecContext(ctx, qwp.Query, qwp.Params...)
			if err != nil {
				return fmt.Errorf("executing query %q: %w", qwp.Query, err)
			}
		}

		return nil
	})
}
